using System;using System.Linq;using System.Collections.Generic;using System.Security.Cryptography;using Mono.Cecil;using Mono.Cecil.Cil;
class ComparePatch{static IEnumerable<TypeDefinition> Types(TypeDefinition t){yield return t;foreach(var n in t.NestedTypes)foreach(var x in Types(n))yield return x;}static string C(Instruction i,List<Instruction> list){object op=i.Operand;var target=op as Instruction;var targets=op as Instruction[];return i.OpCode+" "+(target!=null?"target"+list.IndexOf(target):targets!=null?String.Join(",",targets.Select(t=>list.IndexOf(t))):Convert.ToString(op));}static string H(byte[] b){using(var h=SHA256.Create())return BitConverter.ToString(h.ComputeHash(b));}static void Main(string[] a){using(var o=AssemblyDefinition.ReadAssembly(a[0]))using(var p=AssemblyDefinition.ReadAssembly(a[1])){if(o.Name.FullName!=p.Name.FullName||o.MainModule.Mvid!=p.MainModule.Mvid)throw new Exception("Identity changed");var ot=o.MainModule.Types.SelectMany(Types).ToArray();var pt=p.MainModule.Types.SelectMany(Types).ToArray();if(ot.Length!=pt.Length)throw new Exception("Type count");int edits=0,methods=0,instructions=0;for(int t=0;t<ot.Length;t++){if(ot[t].FullName!=pt[t].FullName||ot[t].Fields.Count!=pt[t].Fields.Count||ot[t].Methods.Count!=pt[t].Methods.Count)throw new Exception("Structure changed");for(int m=0;m<ot[t].Methods.Count;m++){var x=ot[t].Methods[m];var y=pt[t].Methods[m];if(x.FullName!=y.FullName||x.HasBody!=y.HasBody)throw new Exception("Signature changed");methods++;if(!x.HasBody)continue;var original=x.Body.Instructions.ToList();var patched=y.Body.Instructions.ToList();if(x.DeclaringType.FullName=="ShopOS.OsMusic"&&x.Name=="Update"){var guard=patched.Skip(4).Take(7).ToArray();if(guard[0].OpCode!=OpCodes.Call||((MethodReference)guard[0].Operand).Name!="get_IsMac"||guard[1].OpCode!=OpCodes.Brfalse||guard[5].OpCode!=OpCodes.Brtrue||guard[6].OpCode!=OpCodes.Ret||((MethodReference)guard[4].Operand).Name!="CanSelfUpdate"||guard[1].Operand!=patched[11]||guard[5].Operand!=patched[11])throw new Exception("Invalid macOS self-update guard");patched.RemoveRange(4,7);}if(original.Count!=patched.Count||x.Body.ExceptionHandlers.Count!=y.Body.ExceptionHandlers.Count)throw new Exception("Body structure changed");for(int n=0;n<x.Body.Instructions.Count;n++){instructions++;var i=original[n];var j=patched[n];if(C(i,original)==C(j,patched))continue;var mr=j.Operand as MethodReference;if(mr==null||mr.DeclaringType.FullName!="TCG.NativeCompatibility.NativeToolPaths")throw new Exception("Unexpected IL difference "+x.FullName+" "+i+" => "+j);edits++;}}}if(edits!=6)throw new Exception("Expected6 edits");if(o.MainModule.Resources.Count!=p.MainModule.Resources.Count)throw new Exception("Resource count");for(int i=0;i<o.MainModule.Resources.Count;i++){var x=o.MainModule.Resources[i];var y=p.MainModule.Resources[i];if(x.Name!=y.Name)throw new Exception("Resource name");if(x is EmbeddedResource&&H(((EmbeddedResource)x).GetResourceData())!=H(((EmbeddedResource)y).GetResourceData()))throw new Exception("Resource content changed");}Console.WriteLine("Verified "+methods+" methods / "+instructions+" instructions; exactly6 allowed dispatch edits plus macOS external-tool self-update guard, assembly identity/MVID/resources preserved");}}}
